// Turns the desktop's shipped skills into a module the phone bundle can carry.
//
// `import.meta.glob` would be the obvious way to read that folder, but only Vite
// resolves it — the phone bridge is bundled by esbuild, which leaves the call in
// place and throws `import_meta.glob is not a function` before `window.piDesktop`
// is installed. So the folder is read here, at build time, and emitted as plain
// data that both bundlers understand.
//
//   node scripts/build-skills.mjs
//
// The output is generated, git-ignored, and regenerated by predev / prebuild /
// pretest / build:shared, so it cannot go stale between a skill edit and a build.

import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const appRoot = resolve(here, "..");
const repoRoot = resolve(appRoot, "../..");
const source = join(repoRoot, "apps/desktop/resources/skills");
const target = join(appRoot, "src/agent/skills.generated.ts");

const files = readdirSync(source)
  .filter((name) => name.toLowerCase().endsWith(".md"))
  .sort();

const entries = files.map((file) => ({
  file,
  body: readFileSync(join(source, file), "utf8"),
}));

const contents = [
  "// GENERATED by apps/mobile/scripts/build-skills.mjs — do not edit by hand.",
  "// Source: apps/desktop/resources/skills/*.md (one folder, both surfaces).",
  "",
  "export type GeneratedSkillFile = { file: string; body: string };",
  "",
  `export const SKILL_FILES: GeneratedSkillFile[] = ${JSON.stringify(entries)};`,
  "",
].join("\n");

mkdirSync(dirname(target), { recursive: true });
writeFileSync(target, contents, "utf8");
console.log(`[skills] ${entries.length} skills → ${target}`);
